insert into public.verse_translations (verse_id, translation_id, text, approval_status, content_version)
values ('78:40', 'en-sahih-international', 'Indeed, We have warned you of an impending punishment on the Day when a man will observe what his hands have put forth and the disbeliever will say, "Oh, I wish that I were dust!"', 'approved', 1)
